actions.script:
def scope=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call()
def org=scope.activeOrgId;def admin=ec.user.isInGroup('ADMIN')
def labels=[];def tpl=null
def fail={int status,String message -> ec.web.response.setStatus(status);ec.web.sendTextResponse('<!DOCTYPE html><html><body><p>'+message+'</p></body></html>','text/html',null)}
def access={String kind,String id -> ec.service.sync().name('zenith.barcode.BarcodeServices.assert#RecordAccess').parameters([kind:kind,recordId:id,write:false]).call()}
def append={Map label,int qty ->
    if(qty<1 || qty>2000 || labels.size()+qty>2000){fail(400,'Choose between 1 and 2000 labels per preview.');return false}
    for(int i=0;i<qty;i++)labels.add(label);return true
}
if(printJobId){
    def checked=access('job',printJobId);if(!checked.allowed){fail(403,'You do not have access to these labels.');return};def job=checked.record
    if(job.labelId){def t=access('label',job.labelId);if(!t.allowed || t.record.organizationPartyId!=job.organizationPartyId){fail(403,'Print job template ownership is inconsistent.');return};tpl=t.record}
    def rows=ec.entity.find('zenith.erp.barcode.BarcodePrintJobItem').condition('printJobId',printJobId).list()
    for(def item in rows){
        def prd=ec.entity.find('mantle.product.Product').condition('productId',item.productId).one()
        if(!prd || prd.ownerPartyId!=job.organizationPartyId || item.organizationPartyId!=job.organizationPartyId){fail(403,'Print job product ownership is inconsistent.');return}
        // Match the captured value, rather than borrowing the CURRENT primary's format.
        def bc=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',job.organizationPartyId).condition('productId',item.productId).condition('barcodeValue',item.barcodeValue).one()
        if(!append([value:item.barcodeValue,type:bc?.barcodeTypeEnumId ?: 'BctInternal',name:prd.productName ?: item.productId,sku:prd.pseudoId ?: '',price:prd.mrpAmount],(item.quantity ?: 0) as int))return
    }
}else if(barcodeId){
    def checked=access('barcode',barcodeId);if(!checked.allowed){fail(403,'You do not have access to these labels.');return};def bc=checked.record
    def prd=ec.entity.find('mantle.product.Product').condition('productId',bc.productId).one()
    if(bc.isActive!='Y' || !prd || prd.ownerPartyId!=bc.organizationPartyId ||
        (prd.salesDiscontinuationDate && prd.salesDiscontinuationDate <= ec.user.nowTimestamp)){
        fail(400,'This barcode is unavailable for current products.');return}
    if(bc.organizationPartyId)tpl=ec.entity.find('zenith.erp.barcode.BarcodeLabel').condition('organizationPartyId',bc.organizationPartyId).condition('isDefault','Y').one()
    append([value:bc.barcodeValue,type:bc.barcodeTypeEnumId,name:prd.productName ?: bc.productId,sku:prd.pseudoId ?: '',price:prd.mrpAmount],1)
}else if(productIds){
    if(!org){fail(403,'Select an active organization before printing labels.');return}
    def count=copies?.toString() ?: '1'
    if(!(count==~ /[0-9]{1,3}/) || count.toInteger()<1 || count.toInteger()>200){fail(400,'Copies must be a whole number from 1 to 200.');return}
    int qty=count.toInteger();def ids=productIds.toString().split(',').collect{it.trim()}.findAll{it}.unique()
    if(!ids || ids.size()>500 || ids.size()*qty>2000){fail(400,'Choose at most 2000 labels per preview.');return}
    if(labelId){def t=access('label',labelId);if(!t.allowed || t.record.organizationPartyId!=org){fail(403,'Choose a template from the active organization.');return};tpl=t.record}
    else if(w || h || showName || showPrice || showSku){tpl=[labelWidth:w ?: 50,labelHeight:h ?: 30,columnsPerRow:3,showProductName:showName ?: 'Y',showPrice:showPrice ?: 'Y',showSku:showSku ?: 'N']}
    else tpl=ec.entity.find('zenith.erp.barcode.BarcodeLabel').condition('organizationPartyId',org).condition('isDefault','Y').one()
    for(def pid in ids){
        def result=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ProductLabel').parameters([productId:pid]).call()
        if(ec.message.hasError() || result.label?.owner!=org){fail(403,'Choose products from the active organization.');return}
        if(!append(result.label,qty))return
    }
}else{fail(400,'Choose a barcode, print job or product selection.');return}
int columns;BigDecimal width;BigDecimal height
try{
    columns=(tpl?.columnsPerRow ?: 3) as int;width=new BigDecimal((tpl?.labelWidth ?: 50).toString());height=new BigDecimal((tpl?.labelHeight ?: 30).toString())
    if(columns<1 || columns>10 || width<=0 || width>300 || height<=0 || height>300)throw new IllegalArgumentException()
}catch(Exception e){fail(400,'The label dimensions or columns are invalid.');return}
def format=[BctEan13:'EAN13',BctEan8:'EAN8',BctUpcA:'UPC',BctUpcE:'UPCE',BctCode128:'CODE128',BctCode39:'CODE39',BctInternal:'CODE128',BctQrCode:'QR']
for(def label in labels){label.format=format[label.type];if(!label.format){fail(400,'A label has an unsupported barcode type.');return}}
// JSON escapes all script terminators/control characters; barcode input never becomes executable JS.
def payload=groovy.json.JsonOutput.toJson(labels).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
def esc={value -> (value ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'",'&#39;')}
def currency=null
if(org)currency=ec.entity.find('zenith.erp.base.CompanySettings').condition('organizationPartyId',org).condition('settingKey','CURRENCY_UOM_ID').one()?.settingValue
def sb=new StringBuilder("<!DOCTYPE html><html><head><meta charset='utf-8'><title>Barcode Labels</title><link rel='stylesheet' href='/zenithstatic/css/barcode-labels.css?v=1'>")
sb.append("<style>.grid{grid-template-columns:repeat("+columns+","+width.toPlainString()+"mm)}.lbl{width:"+width.toPlainString()+"mm;height:"+height.toPlainString()+"mm}</style></head><body>")
sb.append("<div class='noprint'><button id='print-labels' disabled>Print</button> <b>"+labels.size()+"</b> label(s)<p id='label-status' role='status'>Preparing labels…</p></div><div class='preview'><div class='grid'>")
labels.eachWithIndex{lab,idx ->
    sb.append("<div class='lbl' data-index='"+idx+"'>")
    if(!tpl || tpl.showProductName=='Y')sb.append("<div class='nm'>"+esc(lab.name)+"</div>")
    if(lab.format=='QR')sb.append("<div class='qr' id='q"+idx+"'></div>");else sb.append("<svg class='bc' id='b"+idx+"'></svg>")
    if(tpl?.showSku=='Y' && lab.sku)sb.append("<div class='sk'>"+esc(lab.sku)+"</div>")
    if((!tpl || tpl.showPrice=='Y') && lab.price!=null)sb.append("<div class='pr'>"+esc(currency ? currency+' ' : '')+(lab.price as BigDecimal).setScale(2,java.math.RoundingMode.HALF_UP)+"</div>")
    if(tpl?.showMrp=='Y' && lab.price!=null)sb.append("<div class='pr'>MRP: "+esc(currency ? currency+' ' : '')+(lab.price as BigDecimal).setScale(2,java.math.RoundingMode.HALF_UP)+"</div>")
    sb.append('</div>')
}
sb.append("</div></div><script type='application/json' id='label-data'>"+payload+"</script><script src='/zenithstatic/js/JsBarcode.all.min.js'></script><script src='/zenithstatic/js/barcode-qrcode.min.js?v=1'></script><script src='/zenithstatic/js/barcode-label-renderer.js?v=1'></script></body></html>")
ec.web.sendTextResponse(sb.toString(),'text/html',null)

pre-actions.script:
// Evaluate the pure write predicate explicitly for view-only users; never inherit a fail-open UI flag.
def permission=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:'barcode']).disableAuthz().call()
modCanWrite=permission.canWrite==true
